    public static int blLine(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, byte[] b, int page, int x, int y, int size) {
        // One line on `page` from x at y: the words of b (split at spaces) in type of `size` (centipoints), a word 24/11 of the size wide and a word 28/11 of it apart, the line 100 taller than the type,
        // its baseline 200 above its bottom.
        int w0 = Evidence.wdCount(wd);
        int n = emon.Port.blobLen(b);
        int y1 = y + (size + 100);
        int ww = (size * 24) / 11;
        int st = (size * 28) / 11;
        int s = 0;
        int k = 0;
        int i = 0;
        int xe = x;
        while (k <= n) {
            if ((k == n) || (emon.Port.blobU8(b, k) == 32)) {
                if (k > s) {
                    int ts = emon.Port.cellsLen(et);
                    int wx = x + (i * st);
                    int wx1 = wx + ww;
                    Model.textAppendUtf8(et, b, s, k);
                    int tl = emon.Port.cellsLen(et) - ts;
                    int r = Evidence.wdNew(wd, page, wx, y, wx1, y1, wx, y1 - 200, wx1, y1 - 200, 0, 0, ts, tl, -1, -1, -1);
                    Evidence.wdSet(wd, r, Evidence.wfSize(), size);
                    Evidence.wdSet(wd, r, Evidence.wfFont(), 0);
                    xe = wx1;
                    i += 1;
                }
                s = k + 1;
            }
            k += 1;
        }
        Evidence.lnNew(ln, page, x, y, xe, y1, x, y1 - 200, xe, y1 - 200, 0, 0, w0, Evidence.wdCount(wd) - w0);
        return 0;
    }
