    public static int blFind(emon.Port.Cells nodes, int kind, int nth) {
        // The nth node (from 0) of the kind, -1 when there are not so many.
        int n = Model.nodeCount(nodes);
        int i = 0;
        int seen = 0;
        while (i < n) {
            if (Model.nodeKind(nodes, i) == kind) {
                if (seen == nth) {
                    return i;
                }
                seen += 1;
            }
            i += 1;
        }
        return -1;
    }
    public static int blYes(int n) {
        if (n >= 0) {
            return 1;
        }
        return 0;
    }
    public static int blOwn(emon.Port.Cells nodes, emon.Port.Cells text, int n, byte[] b) {
        // 1 when node n's own text is the ASCII text b.
        int start = Model.nodeTextStart(nodes, n);
        int i = 0;
        if (Model.nodeTextLen(nodes, n) != emon.Port.blobLen(b)) {
            return 0;
        }
        while (i < emon.Port.blobLen(b)) {
            if (emon.Port.cellsAt(text, start + i) != emon.Port.blobU8(b, i)) {
                return 0;
            }
            i += 1;
        }
        return 1;
    }
    public static void testAFootnoteDoesNotGoOnInTheBodyOfTheNextPage() {
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells nodes = emon.Port.newCells();
        emon.Port.Cells attrs = emon.Port.newCells();
        emon.Port.Cells regions = emon.Port.newCells();
        emon.Port.Cells text = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        // P12.7 (smoke B N1): page 1 ends with a footnote in 8 pt whose last line stops at a hyphen; page 2 begins with body type that does not begin with a capital's full stop. The next page's body was the
        // footnote's continuation (a hyphen, a line that reaches the edge, no full stop); a footnote's text goes on only in type of its own size.
        blLine(wd, ln, et, emon.Testport.textBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 1, 7200, 5000, 1100);
        blLine(wd, ln, et, emon.Testport.textBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 1, 7200, 6400, 1100);
        blLine(wd, ln, et, emon.Testport.textBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 1, 7200, 7800, 1100);
        blLine(wd, ln, et, emon.Testport.textBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 1, 7200, 9200, 1100);
        blLine(wd, ln, et, emon.Testport.textBlob("4 We note that in the literature and the usage of the model the bidirectional Trans-"), 1, 7200, 70000, 800);
        blLine(wd, ln, et, emon.Testport.textBlob("Input Output Representations To make BERT handle a variety of tasks our input is able"), 2, 7200, 5000, 1100);
        blLine(wd, ln, et, emon.Testport.textBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 2, 7200, 6400, 1100);
        blLine(wd, ln, et, emon.Testport.textBlob("former is often referred to as a transformer encoder"), 2, 7200, 70000, 800);
        blModel(wd, ln, et, 2, nodes, attrs, regions, text, pages);
        int note = blFind(nodes, Model.nkNote(), 0);
        int np = Model.nodeFirstChild(nodes, note);
        emon.Testport.assertEq(blYes(note), 1, "the small line with the marker 4 at the foot of page 1 is a footnote");
        emon.Testport.assertEq(blOwn(nodes, text, np, emon.Testport.textBlob("We note that in the literature and the usage of the model the bidirectional Trans-")), 1, "the footnote is its own line and not the next page's body");
    }
